/** 起一个装好桩 + 真 background + 真 content 的页面。pagePath 换 mock 页（xxyy 适配用）。 */
async function openPage(over, baseOverride, pagePath) {
  const p = await browser.newPage();
  await p.setViewport({ width: 1280, height: 900 });
  p.on('pageerror', (e) => { console.log('   [page error]', e.message); failures++; });
  await p.evaluateOnNewDocument(chromeShim, Object.assign(SHIM_BASE(),
    { version: JSON.parse(fs.readFileSync(path.join(EXT_DIR, 'manifest.json'), 'utf8')).version }, over || {}));
  await p.goto(`${baseOverride || BASE}${pagePath || '/mock-fomo.html'}`, { waitUntil: 'domcontentloaded' });
  await p.addScriptTag({ content: BG_SRC });
  await p.addScriptTag({ content: CT_SRC });
  await sleep(150);
  return p;
}

/** 起一个装好 storage.sync（可预置 seed）的设置面板页，用来测 openMode 下拉与老 autoOpen 迁移。 */
async function openPopup(seed) {
  const pp = await browser.newPage();
  await pp.setViewport({ width: 340, height: 660 });
  await pp.evaluateOnNewDocument((seedObj) => {
    const store = Object.assign({}, seedObj || {});
    window.__store = store;
    const mkArea = (backing) => ({
      get(keys, cb) { const out = {}; if (keys && typeof keys === 'object') for (const k in keys) out[k] = (k in backing) ? backing[k] : keys[k]; if (cb) setTimeout(() => cb(out), 0); return Promise.resolve(out); },
      set(o, cb) { Object.assign(backing, o); if (cb) setTimeout(cb, 0); return Promise.resolve(); },
      remove(k, cb) { const arr = Array.isArray(k) ? k : [k]; for (const x of arr) delete backing[x]; if (cb) setTimeout(cb, 0); return Promise.resolve(); },
    });
    window.__local = {};
    window.chrome = {
      storage: { sync: mkArea(store), local: mkArea(window.__local), onChanged: { addListener() {} } },
      permissions: { request: () => Promise.resolve(true), contains: () => Promise.resolve(true) },
    };
  }, seed || {});
  await pp.goto(`${BASE}/`, { waitUntil: 'domcontentloaded' }).catch(() => {});
  await pp.setContent(fs.readFileSync(path.join(EXT_DIR, 'popup.html'), 'utf8')
    .replace('<script src="popup.js"></script>', '<script>' + fs.readFileSync(path.join(EXT_DIR, 'popup.js'), 'utf8') + '</script>'));
  await sleep(250);
  return pp;
}

